                                    ),
                                  ],
                                ),
                                const Spacer(),
                                Icon(
                                  card.isCollected ? Icons.album : Icons.lock_outline,
                                  size: 42,
                                  color: card.isCollected ? Colors.amber : Colors.grey.shade700,
